mapper.update:
UPDATE merchant_npc_knowledge_head SET version=#{row.version},revision_id=#{row.id}
WHERE merchant_id=#{row.merchantId} AND owner_member_id=#{row.ownerMemberId} AND version=#{expectedVersion}
  AND EXISTS(SELECT 1 FROM mms_merchant m WHERE m.id=#{row.merchantId} AND m.member_id=#{row.ownerMemberId}
    AND m.status=1 AND m.account_status=1 AND m.del_flag=0)

UPDATE merchant_npc_knowledge_revision SET audit_task_id=#{row.auditTaskId}
WHERE id=#{row.id} AND merchant_id=#{row.merchantId} AND owner_member_id=#{row.ownerMemberId}
  AND version=#{row.version} AND content_hash=#{row.contentHash} AND audit_task_id IS NULL
  AND EXISTS(SELECT 1 FROM mms_merchant m WHERE m.id=#{row.merchantId} AND m.member_id=#{row.ownerMemberId}
    AND m.status=1 AND m.account_status=1 AND m.del_flag=0)
